import sys
input = sys.stdin.read

MOD = 998244353

def power(base, exp, mod):
    res = 1
    cur = base % mod
    while exp > 0:
        if exp & 1:
            res = (res * cur) % mod
        cur = (cur * cur) % mod
        exp >>= 1
    return res

def nCr(n, r, fact, invFact, mod):
    return fact[n] * invFact[r] % mod * invFact[n - r] % mod

def modInverse(a, m):
    return power(a, m - 2, m)

def main():
    data = list(map(int, input().split()))
    n = data[0]
    k = data[1]
    if k >= n:
        print(0)
        return
    c = n - k
    factorials = [1] * (2 * n)
    invFactorials = [1] * (2 * n)
    for i in range(1, 2 * n):
        factorials[i] = (factorials[i - 1] * i) % MOD
    invFactorials[2 * n - 1] = modInverse(factorials[2 * n - 1], MOD)
    for i in range(2 * n - 2, -1, -1):
        invFactorials[i] = (invFactorials[i + 1] * (i + 1)) % MOD
    answer = 0
    for a in range(1, c + 1):
        term = (power(a, n, MOD) * nCr(c, a, factorials, invFactorials, MOD)) % MOD
        if a % 2 == 0:
            answer += term
        else:
            answer -= term
    answer %= MOD
    answer = (answer * nCr(n, c, factorials, invFactorials, MOD)) % MOD
    if k > 0:
        answer = (answer * 2) % MOD
    print(answer)

if __name__ == "__main__":
    main()

